class Wallet:
    def __init__(self):
        self.balance = 0

    def add(self, amount):
        self.balance += amount

    def spend(self, amount):
        if amount > self.balance:
            return False
        self.balance -= amount
        return True


w = Wallet()
w.add(100)
print(w.spend(30))
print(w.spend(100))
print(w.balance)

