task.solution:
import sys

rows = sys.stdin.read().splitlines()
spent = {}
for row in rows:
    if not row.strip():
        continue
    name, amount = row.split()
    spent[name] = spent.get(name, 0) + int(amount)
for name, total in sorted(spent.items(), key=lambda p: p[1], reverse=True):
    print(f"{name}: {total}")
print(f"итого: {sum(spent.values())}")
